DELIMITER ;;
/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_auto_create_notification` AFTER INSERT ON `announcements_bulletin` FOR EACH ROW BEGIN 
  IF NEW.target_audience = 'all' OR NEW.target_audience = 'staff' THEN
    INSERT INTO notifications (
      user_id,
      title,
      message,
      type,
      priority,
      read_status,
      created_at
    )
    SELECT u.id,
      NEW.title,
      SUBSTRING(NEW.content, 1, 200),
      'announcement',
      CASE 
        WHEN NEW.priority = 'normal' THEN 'medium'
        WHEN NEW.priority = 'critical' THEN 'high'
        ELSE NEW.priority
      END,
      'unread',
      NOW()
    FROM users u
    WHERE u.status = 'active' AND u.id <> NEW.published_by;
  END IF;
  INSERT INTO system_events (event_type, event_data, created_at)
  VALUES (
    'announcement_created',
    JSON_OBJECT(
      'announcement_id', NEW.id,
      'title', NEW.title,
      'audience', NEW.target_audience
    ),
    NOW()
  );
END */;;
