/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_bank_payment_processed` AFTER INSERT ON `bank_transactions` FOR EACH ROW BEGIN 
    IF NEW.status = 'processed' AND NEW.student_id IS NOT NULL THEN
        UPDATE student_fee_balances
        SET balance = balance - NEW.amount,
            last_updated = NOW()
        WHERE student_id = NEW.student_id
        ORDER BY academic_term_id DESC
        LIMIT 1;
INSERT INTO school_transactions (
    student_id,
    source,
    reference,
    amount,
    transaction_date,
    status,
    details
  )
VALUES (
    NEW.student_id,
    'bank',
    NEW.transaction_ref,
    NEW.amount,
    NEW.transaction_date,
    'confirmed',
    JSON_OBJECT(
      'bank',
      NEW.bank_name,
      'account',
      NEW.account_number
    )
  );
END IF;
END */;;
