  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cash_recon_date` (`reconciliation_date`,`cashier_id`),
  KEY `idx_cash_recon_date` (`reconciliation_date`)
