  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `completed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_student_year` (`student_id`,`academic_year_id`),
  KEY `idx_student` (`student_id`),
  KEY `idx_academic_year` (`academic_year_id`),
  KEY `idx_class_stream` (`class_id`,`stream_id`),
  KEY `idx_assignment` (`class_assignment_id`),
  KEY `idx_enrollment_status` (`enrollment_status`),
  KEY `idx_promotion_status` (`promotion_status`),
  KEY `idx_year_student` (`academic_year_id`,`student_id`),
  KEY `class_enrollments_ibfk_4` (`stream_id`),
  CONSTRAINT `class_enrollments_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `class_enrollments_ibfk_2` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `class_enrollments_ibfk_3` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `class_enrollments_ibfk_4` FOREIGN KEY (`stream_id`) REFERENCES `class_streams` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `class_enrollments_ibfk_5` FOREIGN KEY (`class_assignment_id`) REFERENCES `class_year_assignments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student enrollment per academic year - one record per student per year';
