        SET current_enrollment = current_enrollment + 1 
        WHERE id = NEW.class_assignment_id;
    END IF;
    
    
    UPDATE academic_years 
    SET total_students = (SELECT COUNT(*) FROM class_enrollments WHERE academic_year_id = NEW.academic_year_id)
