/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_auto_create_default_stream` AFTER INSERT ON `classes` FOR EACH ROW BEGIN
    DECLARE v_stream_count INT;
    DECLARE v_default_stream_name VARCHAR(50);
    
    SELECT COUNT(*) INTO v_stream_count
    FROM class_streams
    WHERE class_id = NEW.id;
    
    IF v_stream_count = 0 THEN
        SET v_default_stream_name = NEW.name;
        INSERT INTO class_streams (
            class_id,
            stream_name,
            capacity,
            teacher_id,
            status
        )
        VALUES (
            NEW.id,
            v_default_stream_name,
            NEW.capacity,
            NEW.teacher_id,
            'active'
        );
    END IF;
END */;;
