/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_emit_low_stock_event` AFTER UPDATE ON `inventory_items` FOR EACH ROW BEGIN 
    IF NEW.current_quantity <= NEW.minimum_quantity
       AND OLD.current_quantity > NEW.minimum_quantity THEN
        INSERT INTO system_events (event_type, event_data, created_at)
        VALUES (
            'inventory_low_stock',
            JSON_OBJECT(
                'item_id', NEW.id,
                'item_name', NEW.name,
                'quantity', NEW.current_quantity
            ),
            NOW()
        );
    END IF;
END */;;
