INSERT INTO `leadership_team` VALUES (1,'School Director','School Founder & Director','20+ years in education leadership. Holds a Masters in Educational Management from University of Nairobi.',NULL,'#0d4f2a',NULL,10,1,'2026-04-27 06:18:19','2026-04-27 06:18:19'),(2,'Head Teacher','Head Teacher','B.Ed (Hons), experienced in CBC implementation and school administration. Sets the academic tone for the school.',NULL,'#198754',NULL,20,1,'2026-04-27 06:18:19','2026-04-27 06:18:19'),(3,'Deputy (Academic)','Deputy Head — Academic','Oversees curriculum delivery, lesson plans, timetabling, teacher development, and academic performance monitoring.',NULL,'#1976d2',NULL,30,1,'2026-04-27 06:18:19','2026-04-27 06:18:19'),(4,'Deputy (Discipline)','Deputy Head — Discipline','Manages student conduct, welfare, community relations, and the boarding programme pastoral care.',NULL,'#7b1fa2',NULL,40,1,'2026-04-27 06:18:19','2026-04-27 06:18:19'),(5,'The Bursar','School Bursar / Accountant','CPA-K certified. Manages school finances, fee collection, budgets, payroll, and financial reporting.',NULL,'#e65100',NULL,50,1,'2026-04-27 06:18:19','2026-04-27 06:18:19'),(6,'Admissions Officer','Admissions Officer','Handles student intake, placement assessments, records management, and parent liaison throughout the admission process.',NULL,'#00695c',NULL,60,1,'2026-04-27 06:18:19','2026-04-27 06:18:19');
