/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_log_payment_transaction` AFTER INSERT ON `payment_transactions` FOR EACH ROW BEGIN
    INSERT INTO system_events (event_type, event_data, created_at)
    VALUES (
        'payment_received',
        JSON_OBJECT(
            'payment_id', NEW.id,
            'student_id', NEW.student_id,
            'parent_id', NEW.parent_id,
            'amount', NEW.amount_paid,
            'method', NEW.payment_method,
            'reference', NEW.reference_no,
            'receipt', NEW.receipt_no
        ),
        NOW()
    );
END */;;
