INSERT INTO `roles` VALUES (2,'System Administrator','[ROOT/SUPER USER] Complete system access: codebase management, database management, system configuration, all permissions, full technical control. This is the developer/technical admin account.','system',1,1,1,'2025-12-06 12:54:06','2026-04-17 12:50:09'),(3,'Director','School Director - Financial reports viewing, approvals for transactions, fees structure updates, transport fees, payroll approvals, strategic decisions','school',0,1,1,'2025-12-06 12:54:06','2026-04-17 12:50:09'),(4,'School Administrator','School Administrator - Operational school admin: manages school users, roles & permissions, provides support to all staff, accesses most school operations (academic, students, staff, communications). Does NOT have codebase/database access.','school',0,1,1,'2025-12-06 12:54:06','2026-04-17 12:50:09'),(5,'Headteacher','Headteacher - Academic year scheduling, student admissions (with deputies), timetabling, academic oversight, parent communication, overall school management','school',0,1,1,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(6,'Deputy Head - Academic','Deputy Headteacher (Academic) - Student admissions, student promotion, timetabling, academic oversight, parent communication','school',0,1,1,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(7,'Class Teacher','Class Teacher - Class management, attendance, assessments, results, lesson plans, parent communication, timetabling review','school',0,1,13,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(8,'Subject Teacher','Subject Teacher - Subject teaching, exams, assessments, results, lesson plans, timetabling review','school',0,1,13,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(9,'Intern/Student Teacher','Intern/Student Teacher - Learning internship, lesson plan viewing, teaching observation, limited access','school',0,1,1,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(10,'Accountant','Accountant - Complete financial management: fees, payroll, budgets, reconciliation, financial reports, P9/payslip generation, fee structure updates, transport fees, worker payments, account management for academic years','school',0,1,1,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(14,'Inventory Manager','Inventory Manager - School uniforms store management, uniform inventory, requisitions, stock control','school',0,1,1,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(16,'Cateress','Cateress - Kitchen management: all kitchen staff coordination (chefs, cooks), meal planning, food store management, inventory for kitchen supplies','school',0,1,1,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(18,'Boarding Master','Boarding Master - Boarding facility management, student welfare in boarding, health monitoring, boarding discipline','school',0,1,1,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(21,'Talent Development','Talent Development Manager - Games, sports, music, talent acquisition and development, student activities, competitions, performances','school',0,1,1,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(23,'Driver','Driver - Student transport, route management, vehicle maintenance reporting','school',0,1,1,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(24,'Chaplain','Chaplain - Spiritual welfare, student counseling, pastoral care, chapel services','school',0,1,1,'2025-12-06 12:54:07','2026-04-17 12:50:09'),(32,'Kitchen Staff','[TRACKING ONLY] Kitchen worker - No system access. Managed by Cateress. For payroll and records only.','school',0,1,1,'2025-12-10 08:19:14','2026-04-17 12:50:09'),(33,'Security Staff','[TRACKING ONLY] Security personnel - No system access. For payroll and records only.','school',0,1,1,'2025-12-10 08:19:14','2026-04-17 12:50:09'),(34,'Janitor','[TRACKING ONLY] Maintenance and cleaning staff - No system access. For payroll and records only.','school',0,1,1,'2025-12-10 08:19:14','2026-04-17 12:50:09'),(63,'Deputy Head - Discipline','Deputy Headteacher (Discipline) - Student admissions, discipline management, timetabling, parent communication','school',0,1,1,'2025-12-12 16:12:14','2026-04-17 12:50:09'),(64,'Staff','Default staff role','school',0,1,0,'2025-12-31 05:54:22','2025-12-31 05:54:22'),(65,'TeacherTest','Temporary test teacher role','school',0,1,2,'2025-12-31 06:11:50','2026-04-17 12:50:09'),(66,'TeacherTest_1767163062','Temporary test teacher role','school',0,1,1,'2025-12-31 06:37:42','2026-04-17 12:50:09'),(67,'TeacherTest_1767164152','Temporary test teacher role','school',0,1,1,'2025-12-31 06:55:52','2026-04-17 12:50:09'),(68,'TeacherTest_1767164188','Temporary test teacher role','school',0,1,1,'2025-12-31 06:56:28','2026-04-17 12:50:09'),(69,'TeacherTest_1767165995','Temporary test teacher role','school',0,1,1,'2025-12-31 07:26:36','2026-04-17 12:50:09'),(70,'TeacherTest_1767166489','Temporary test teacher role','school',0,1,1,'2025-12-31 07:34:50','2026-04-17 12:50:09');
