INSERT INTO `school_facilities` VALUES (1,'bi-building','Modern Classrooms','32 well-ventilated, fully-furnished classrooms equipped for CBC project-based learning.',10,1),(2,'bi-laptop','ICT Computer Lab','40-station computer laboratory with high-speed fibre internet and CBC educational software.',20,1),(3,'bi-book','School Library','Over 12,000 books including CBC-aligned reference materials, fiction, and digital resource tablets.',30,1),(4,'bi-heart-pulse','Sick Bay','Fully equipped sick bay managed by a qualified residential nurse available 24/7 for boarding students.',40,1),(5,'bi-house-door','Dormitories','Separate boys and girls dormitories with houseparents on duty around the clock.',50,1),(6,'bi-cup-hot','Dining Hall','Spacious dining hall serving three balanced, nutritious meals daily for all boarding students.',60,1),(7,'bi-flag','Sports Grounds','Full-size football pitch, basketball and netball courts, and athletics track.',70,1),(8,'bi-music-note','Music & Arts Room','Dedicated music room with instruments for lessons, choir practice, and the drama club.',80,1),(9,'bi-flask','Science Laboratory','Equipped laboratory for Grade 7–9 integrated science practicals and experiments.',90,1),(10,'bi-wifi','Smart Classrooms','Interactive smart boards and projectors integrated into the Grade 6–9 classroom experience.',100,1),(11,'bi-person-hearts','Counselling Suite','Private counselling rooms for student welfare, peer mentoring, and pastoral care sessions.',110,1),(12,'bi-shop','School Canteen','Tuck shop stocking approved snacks and scholastic materials. Cashless payment system for boarders.',120,1);
/*!40000 ALTER TABLE `school_facilities` ENABLE KEYS */;
UNLOCK TABLES;

