DROP TABLE IF EXISTS `school_week_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `school_week_config` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `academic_year_id` int(10) unsigned NOT NULL,
  `saturday_classes` tinyint(1) DEFAULT 0 COMMENT '1 = Saturdays are school days (SATURDAY_CLASS session)',
  `sunday_boarding` tinyint(1) DEFAULT 1 COMMENT '1 = Boarding roll call required on Sundays',
  `class_days` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '["Monday","Tuesday","Wednesday","Thursday","Friday"]' CHECK (json_valid(`class_days`)),
  `boarding_days` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"]' CHECK (json_valid(`boarding_days`)),
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_year` (`academic_year_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

