DROP TABLE IF EXISTS `sms_communications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sms_communications` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` int(10) unsigned DEFAULT NULL,
  `student_id` int(10) unsigned DEFAULT NULL,
  `recipient_phone` varchar(20) NOT NULL,
  `message_body` text NOT NULL,
  `template_id` int(10) unsigned DEFAULT NULL,
  `sms_type` enum('academic','fees','attendance','event','emergency','general','report_card') NOT NULL DEFAULT 'general',
  `status` enum('pending','queued','sent','delivered','failed') NOT NULL DEFAULT 'pending',
  `sent_by` int(10) unsigned NOT NULL,
  `sent_at` datetime DEFAULT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `failure_reason` text DEFAULT NULL,
  `external_reference_id` varchar(255) DEFAULT NULL,
  `character_count` int(11) DEFAULT NULL,
  `sms_parts` int(11) DEFAULT 1,
  `cost` decimal(10,2) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `parent_id` (`parent_id`),
  KEY `student_id` (`student_id`),
  KEY `idx_status` (`status`),
  KEY `idx_sms_type` (`sms_type`),
  KEY `idx_recipient` (`recipient_phone`),
  KEY `sent_by` (`sent_by`),
  CONSTRAINT `sms_communications_ibfk_1` FOREIGN KEY (`parent_id`) REFERENCES `parents` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sms_communications_ibfk_2` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sms_communications_ibfk_3` FOREIGN KEY (`sent_by`) REFERENCES `staff` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

