/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_log_sms_delivery` AFTER UPDATE ON `sms_communications` FOR EACH ROW BEGIN
DECLARE v_status_changed BOOLEAN DEFAULT FALSE;
IF OLD.status <> NEW.status THEN
SET v_status_changed = TRUE;
INSERT INTO system_events (event_type, event_data, created_at)
VALUES (
    'sms_status_changed',
    JSON_OBJECT(
      'sms_id',
      NEW.id,
      'old_status',
      OLD.status,
      'new_status',
      NEW.status,
      'parent_id',
      NEW.parent_id
    ),
    NOW()
  );
END IF;
IF NEW.status = 'delivered'
AND OLD.status <> 'delivered' THEN
UPDATE parent_communication_preferences
SET last_sms_date = NOW()
WHERE parent_id = NEW.parent_id;
END IF;
END */;;
DELIMITER ;
