DROP TABLE IF EXISTS `staff_attendance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `staff_attendance` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `staff_id` int(10) unsigned NOT NULL,
  `date` date NOT NULL,
  `academic_year_id` int(10) unsigned DEFAULT NULL,
  `shift` enum('morning','afternoon','evening','night','full_day') NOT NULL DEFAULT 'full_day',
  `status` enum('present','absent','late') NOT NULL,
  `check_in_time` time DEFAULT NULL,
  `expected_check_in` time DEFAULT NULL,
  `check_out_time` time DEFAULT NULL,
  `duty_type_id` int(10) unsigned DEFAULT NULL,
  `leave_id` int(10) unsigned DEFAULT NULL,
  `absence_reason` enum('leave','sick','off_day','unauthorized','other') DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `marked_by` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_staff_date_shift` (`staff_id`,`date`,`shift`),
  KEY `idx_staff_date` (`staff_id`,`date`),
  KEY `marked_by` (`marked_by`),
  KEY `idx_staff_date_status` (`staff_id`,`date`,`status`),
  KEY `fk_staff_duty_type` (`duty_type_id`),
  KEY `fk_staff_leave` (`leave_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1193 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
