/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_update_leave_balance` AFTER UPDATE ON `staff_leaves` FOR EACH ROW BEGIN
    IF NEW.status = 'approved' AND OLD.status = 'pending' THEN
        
        INSERT INTO workflow_notifications (
            workflow_instance_id,
            user_id,
            notification_type,
            title,
            message,
            created_at
        )
        SELECT 
            wi.id,
            NEW.staff_id,
            'leave_approved',
            'Leave Request Approved',
            CONCAT('Your leave request from ', NEW.start_date, ' to ', NEW.end_date, ' has been approved'),
            NOW()
        FROM workflow_instances wi
        WHERE wi.entity_type = 'leave_request' 
        AND wi.entity_id = NEW.id
        LIMIT 1;
    END IF;
END */;;
