/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_log_arrears_creation` AFTER INSERT ON `student_arrears` FOR EACH ROW BEGIN
    INSERT INTO system_events (event_type, event_data, created_at)
    VALUES (
        'arrears_created',
        JSON_OBJECT(
            'student_id', NEW.student_id,
            'arrears_id', NEW.id,
            'amount', NEW.total_arrears,
            'academic_year', NEW.academic_year,
            'status', NEW.arrears_status
        ),
        NOW()
    );
END */;;
DELIMITER ;
