DROP TABLE IF EXISTS `student_attendance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_attendance` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` int(10) unsigned NOT NULL,
  `date` date NOT NULL,
  `status` enum('present','absent','late') NOT NULL,
  `check_in_time` time DEFAULT NULL,
  `check_out_time` time DEFAULT NULL,
  `absence_reason` enum('unexcused','sick','permission','suspension','other') DEFAULT 'unexcused',
  `permission_id` int(10) unsigned DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `class_id` int(10) unsigned DEFAULT NULL,
  `term_id` int(10) unsigned DEFAULT NULL,
  `academic_year_id` int(10) unsigned DEFAULT NULL,
  `register_type` enum('class','boarding','activity') NOT NULL DEFAULT 'class',
  `session_id` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `marked_by` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_attendance_mark` (`student_id`,`date`,`session_id`,`register_type`),
  KEY `idx_student_date` (`student_id`,`date`),
  KEY `class_id` (`class_id`),
  KEY `term_id` (`term_id`),
  KEY `marked_by` (`marked_by`),
  KEY `idx_class_date_status` (`class_id`,`date`,`status`),
  KEY `idx_session_date` (`session_id`,`date`),
  KEY `fk_attendance_permission` (`permission_id`),
  KEY `idx_year_term` (`academic_year_id`,`term_id`),
