/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_update_class_capacity` AFTER INSERT ON `students` FOR EACH ROW BEGIN
UPDATE class_streams cs
SET current_students = (
    SELECT COUNT(*)
    FROM students s
    WHERE s.stream_id = cs.id
  )
WHERE cs.id = NEW.stream_id;
END */;;
DELIMITER ;
