/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_emit_student_status_event` AFTER UPDATE ON `students` FOR EACH ROW BEGIN IF NEW.status != OLD.status THEN
INSERT INTO system_events (event_type, event_data, created_at)
VALUES (
    'student_status_changed',
    JSON_OBJECT(
      'student_id',
      NEW.id,
      'old_status',
      OLD.status,
      'new_status',
      NEW.status
    ),
    NOW()
  );
END IF;
END */;;
DELIMITER ;
