/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_update_student_status` AFTER UPDATE ON `students` FOR EACH ROW BEGIN IF NEW.status IN ('graduated', 'transferred')
  AND OLD.status != NEW.status THEN
INSERT INTO notifications (
    user_id,
    type,
    title,
    message,
    priority,
    created_at
  )
VALUES (
    get_parent_user_id(NEW.id),
    'info',
    'Student Status Update',
    CONCAT('Your child status changed to ', NEW.status),
    'medium',
    NOW()
  );
END IF;
END */;;
DELIMITER ;
