--
-- Table structure for table `system_policies`
--

DROP TABLE IF EXISTS `system_policies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `system_policies` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT 'Policy identifier',
  `display_name` varchar(150) NOT NULL COMMENT 'Human-readable name',
  `rule_type` enum('deny','allow','restrict','require','audit') NOT NULL DEFAULT 'deny',
  `priority` int(11) NOT NULL DEFAULT 0 COMMENT 'Higher = evaluated first',
  `rule_expression` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Policy rule in JSON DSL' CHECK (json_valid(`rule_expression`)),
  `description` varchar(500) DEFAULT NULL,
  `applies_to` enum('role','user','route','domain','global') NOT NULL DEFAULT 'global',
  `target_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of role_ids, user_ids, etc.' CHECK (json_valid(`target_ids`)),
  `effective_from` timestamp NULL DEFAULT NULL COMMENT 'When policy becomes active',
  `effective_until` timestamp NULL DEFAULT NULL COMMENT 'When policy expires',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  KEY `idx_policies_type` (`rule_type`),
  KEY `idx_policies_priority` (`priority`),
  KEY `idx_policies_active` (`is_active`),
  KEY `idx_policies_effective` (`effective_from`,`effective_until`),
  KEY `fk_policies_creator` (`created_by`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `system_policies`
--

LOCK TABLES `system_policies` WRITE;
/*!40000 ALTER TABLE `system_policies` DISABLE KEYS */;
INSERT INTO `system_policies` VALUES (1,'system_admin_no_school_access','System Admin - No School Operations','deny',100,'{\"condition\": \"AND\", \"rules\": [{\"field\": \"role_id\", \"operator\": \"=\", \"value\": 2}, {\"field\": \"route.domain\", \"operator\": \"=\", \"value\": \"SCHOOL\"}]}','System Administrator (Role 2) is forbidden from accessing any SCHOOL domain routes','role','[2]',NULL,NULL,1,NULL,'2025-12-28 17:14:52','2025-12-28 17:14:52'),(2,'school_roles_no_system_access','School Roles - No System Administration','deny',99,'{\"condition\": \"AND\", \"rules\": [{\"field\": \"role_id\", \"operator\": \"NOT IN\", \"value\": [2]}, {\"field\": \"route.domain\", \"operator\": \"=\", \"value\": \"SYSTEM\"}]}','All non-System Admin roles are forbidden from accessing SYSTEM domain routes','domain',NULL,NULL,NULL,1,NULL,'2025-12-28 17:14:52','2025-12-28 17:14:52'),(3,'delegated_permissions_readonly','Delegated Permissions - Read Only','restrict',80,'{\"condition\": \"AND\", \"rules\": [{\"field\": \"permission.is_delegated\", \"operator\": \"=\", \"value\": true}, {\"field\": \"access_type\", \"operator\": \"IN\", \"value\": [\"create\", \"update\", \"delete\"]}]}','Delegated permissions are restricted to view-only access','global',NULL,NULL,NULL,1,NULL,'2025-12-28 17:14:52','2025-12-28 17:14:52');
/*!40000 ALTER TABLE `system_policies` ENABLE KEYS */;
UNLOCK TABLES;

