/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `trg_after_password_change` AFTER UPDATE ON `users` FOR EACH ROW BEGIN
    IF NEW.password != OLD.password THEN
        UPDATE users
        SET password_changed_at = CURRENT_TIMESTAMP
        WHERE id = NEW.id;
    END IF;
END */;;
DELIMITER ;
